using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Pricing;

namespace BARANG.Core.Domain.Inventory;

public enum StockTransactionType{Receipt,Issue,TransferOut,TransferIn,Adjustment,Return,Scrap}
public enum ReservationStatus{Active,PartiallyReleased,Released,Consumed,Expired}
public enum StockTransferStatus{InTransit,Completed,Cancelled}
public enum PurchaseRequestStatus{Draft,Submitted,Closed,Cancelled}
public enum PurchaseOrderStatus{Draft,Submitted,PartiallyReceived,Received,Closed,Cancelled}

public static class InventoryErrors
{
 public static Error UnitMismatch=>Error.Validation("inventory.unit_mismatch");public static Error PricingReapprovalRequired=>Error.BusinessRule("inventory.adjustment.pricing_reapproval_required");public static Error IssuedItemImmutable=>Error.BusinessRule("inventory.adjustment.issued_item_immutable");
 public static Error InvalidData=>Error.Validation("inventory.invalid_data");public static Error NotFound=>Error.NotFound("inventory.resource.not_found");public static Error Insufficient=>Error.BusinessRule("inventory.insufficient_stock");public static Error OverRelease=>Error.BusinessRule("inventory.reservation.over_release");public static Error AlreadyConsumed=>Error.Conflict("inventory.reservation.already_consumed");public static Error DuplicateReference=>Error.Conflict("inventory.duplicate_reference");public static Error InvalidTransition=>Error.BusinessRule("inventory.invalid_transition");public static Error ReasonRequired=>Error.Validation("inventory.reason_required");public static Error OverReceipt=>Error.BusinessRule("purchasing.over_receipt");public static Error Concurrency=>Error.Concurrency("inventory.concurrency_conflict");
}
public static class InventoryText{public static string Code(string? x)=>(x??"").Trim().ToUpperInvariant();public static string? Text(string?x,int max){if(string.IsNullOrWhiteSpace(x))return null;string s=x.Trim();return s.Length<=max?s:null;}}

public sealed class StockTransaction
{
 private StockTransaction(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid WarehouseId{get;private set;}public Guid ProductVariantId{get;private set;}public StockTransactionType TransactionType{get;private set;}public decimal QuantityDelta{get;private set;}public string UomCode{get;private set;}="";public string SourceType{get;private set;}="";public Guid? SourceId{get;private set;}public string Reference{get;private set;}="";public string? ReasonCode{get;private set;}public DateTimeOffset OccurredAtUtc{get;private set;}public Guid ActorUserId{get;private set;}public string CorrelationId{get;private set;}="";public DateTimeOffset CreatedAtUtc{get;private set;}
 public static Result<StockTransaction>Create(Guid company,Guid warehouse,Guid variant,StockTransactionType type,decimal delta,string uom,string source,Guid?sourceId,string reference,string?reason,Guid actor,string correlation,DateTimeOffset occurred,DateTimeOffset now){string u=InventoryText.Code(uom),s=InventoryText.Code(source),r=InventoryText.Code(reference),c=(correlation??"").Trim();if(company==Guid.Empty||warehouse==Guid.Empty||variant==Guid.Empty||actor==Guid.Empty||delta==0||u.Length is <1 or>50||s.Length is <1 or>50||r.Length is <1 or>150||c.Length is <1 or>100)return Result.Failure<StockTransaction>(InventoryErrors.InvalidData);return Result.Success(new StockTransaction{Id=Guid.NewGuid(),CompanyId=company,WarehouseId=warehouse,ProductVariantId=variant,TransactionType=type,QuantityDelta=delta,UomCode=u,SourceType=s,SourceId=sourceId,Reference=r,ReasonCode=InventoryText.Text(reason,100),ActorUserId=actor,CorrelationId=c,OccurredAtUtc=occurred,CreatedAtUtc=now});}
}
public sealed class StockBalance
{
 private StockBalance(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid WarehouseId{get;private set;}public Guid ProductVariantId{get;private set;}public decimal OnHand{get;private set;}public decimal Reserved{get;private set;}public decimal Available=>OnHand-Reserved;public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}
 public static StockBalance Create(Guid company,Guid warehouse,Guid variant,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,WarehouseId=warehouse,ProductVariantId=variant,UpdatedAtUtc=now,Version=1};public Result ApplyOnHand(decimal delta,bool allowNegative,DateTimeOffset now){if(!allowNegative&&OnHand+delta<Reserved)return Result.Failure(InventoryErrors.Insufficient);OnHand+=delta;UpdatedAtUtc=now;Version++;return Result.Success();}public Result Reserve(decimal qty,DateTimeOffset now){if(qty<=0||Available<qty)return Result.Failure(InventoryErrors.Insufficient);Reserved+=qty;UpdatedAtUtc=now;Version++;return Result.Success();}public Result Release(decimal qty,DateTimeOffset now){if(qty<=0||qty>Reserved)return Result.Failure(InventoryErrors.OverRelease);Reserved-=qty;UpdatedAtUtc=now;Version++;return Result.Success();}public Result Consume(decimal qty,DateTimeOffset now){if(qty<=0||qty>Reserved||qty>OnHand)return Result.Failure(InventoryErrors.Insufficient);Reserved-=qty;OnHand-=qty;UpdatedAtUtc=now;Version++;return Result.Success();}
}
public sealed class StockReservation
{
 private StockReservation(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderItemId{get;private set;}public Guid WarehouseId{get;private set;}public Guid ProductVariantId{get;private set;}public string UomCode{get;private set;}="";public decimal RequestedQuantity{get;private set;}public decimal ReservedQuantity{get;private set;}public decimal RemainingQuantity{get;private set;}public ReservationStatus Status{get;private set;}public DateTimeOffset? ExpiresAtUtc{get;private set;}public string IdempotencyKey{get;private set;}="";public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}
 public static StockReservation Create(Guid company,Guid item,Guid warehouse,Guid variant,decimal qty,DateTimeOffset?expires,string key,DateTimeOffset now)=>Create(company,item,warehouse,variant,"",qty,expires,key,now);public static StockReservation Create(Guid company,Guid item,Guid warehouse,Guid variant,string uom,decimal qty,DateTimeOffset?expires,string key,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,OrderItemId=item,WarehouseId=warehouse,ProductVariantId=variant,UomCode=InventoryText.Code(uom),RequestedQuantity=qty,ReservedQuantity=qty,RemainingQuantity=qty,Status=ReservationStatus.Active,ExpiresAtUtc=expires,IdempotencyKey=key.Trim(),CreatedAtUtc=now,UpdatedAtUtc=now,Version=1};public Result Release(decimal qty,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);if(Status is ReservationStatus.Released or ReservationStatus.Consumed or ReservationStatus.Expired||qty<=0||qty>RemainingQuantity)return Result.Failure(InventoryErrors.OverRelease);RemainingQuantity-=qty;Status=RemainingQuantity==0?ReservationStatus.Released:ReservationStatus.PartiallyReleased;UpdatedAtUtc=now;Version++;return Result.Success();}public Result Consume(decimal qty,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);if(Status is ReservationStatus.Released or ReservationStatus.Consumed or ReservationStatus.Expired||qty<=0||qty>RemainingQuantity)return Result.Failure(InventoryErrors.AlreadyConsumed);RemainingQuantity-=qty;Status=RemainingQuantity==0?ReservationStatus.Consumed:ReservationStatus.Active;UpdatedAtUtc=now;Version++;return Result.Success();}public decimal Expire(DateTimeOffset now){if(ExpiresAtUtc>now||Status is ReservationStatus.Released or ReservationStatus.Consumed or ReservationStatus.Expired)return 0;decimal q=RemainingQuantity;RemainingQuantity=0;Status=ReservationStatus.Expired;UpdatedAtUtc=now;Version++;return q;}
}
public sealed class StockTransfer
{
 private StockTransfer(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid SourceWarehouseId{get;private set;}public Guid DestinationWarehouseId{get;private set;}public Guid ProductVariantId{get;private set;}public decimal Quantity{get;private set;}public string UomCode{get;private set;}="";public string Reference{get;private set;}="";public StockTransferStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}
 public static Result<StockTransfer>Create(Guid company,Guid source,Guid destination,Guid variant,decimal qty,string uom,string reference,DateTimeOffset now){if(company==Guid.Empty||source==destination||qty<=0)return Result.Failure<StockTransfer>(InventoryErrors.InvalidData);return Result.Success(new StockTransfer{Id=Guid.NewGuid(),CompanyId=company,SourceWarehouseId=source,DestinationWarehouseId=destination,ProductVariantId=variant,Quantity=qty,UomCode=InventoryText.Code(uom),Reference=InventoryText.Code(reference),Status=StockTransferStatus.InTransit,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result Complete(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);if(Status!=StockTransferStatus.InTransit)return Result.Failure(InventoryErrors.InvalidTransition);Status=StockTransferStatus.Completed;UpdatedAtUtc=now;Version++;return Result.Success();}
}
public sealed class StockShortage
{
 private StockShortage(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderItemId{get;private set;}public Guid WarehouseId{get;private set;}public Guid ProductVariantId{get;private set;}public decimal RequiredQuantity{get;private set;}public decimal AvailableQuantity{get;private set;}public decimal ShortageQuantity{get;private set;}public bool IsActive{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public long Version{get;private set;}public static StockShortage Create(Guid company,Guid item,Guid warehouse,Guid variant,decimal required,decimal available,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,OrderItemId=item,WarehouseId=warehouse,ProductVariantId=variant,RequiredQuantity=required,AvailableQuantity=available,ShortageQuantity=Math.Max(0,required-available),IsActive=true,CreatedAtUtc=now,Version=1};public void Close(){IsActive=false;Version++;}
}
public sealed class PurchaseRequest
{
 private PurchaseRequest(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid WarehouseId{get;private set;}public Guid RequestedByUserId{get;private set;}public string RequestNumber{get;private set;}="";public string Reason{get;private set;}="";public Guid? SourceShortageId{get;private set;}public PurchaseRequestStatus Status{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static Result<PurchaseRequest>Create(Guid company,Guid warehouse,Guid actor,string reason,Guid?shortage,DateTimeOffset now){string? r=InventoryText.Text(reason,500);if(r is null)return Result.Failure<PurchaseRequest>(InventoryErrors.ReasonRequired);Guid id=Guid.NewGuid();return Result.Success(new PurchaseRequest{Id=id,CompanyId=company,WarehouseId=warehouse,RequestedByUserId=actor,RequestNumber=$"PR-{now.Year}-{id.ToString("N")[..10].ToUpperInvariant()}",Reason=r,SourceShortageId=shortage,Status=PurchaseRequestStatus.Draft,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result Submit(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);if(Status!=PurchaseRequestStatus.Draft)return Result.Failure(InventoryErrors.InvalidTransition);Status=PurchaseRequestStatus.Submitted;UpdatedAtUtc=now;Version++;return Result.Success();}
}
public sealed class PurchaseRequestItem{private PurchaseRequestItem(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid PurchaseRequestId{get;private set;}public Guid ProductVariantId{get;private set;}public string UomCode{get;private set;}="";public decimal RequestedQuantity{get;private set;}public static PurchaseRequestItem Create(Guid company,Guid request,Guid variant,decimal qty)=>Create(company,request,variant,"",qty);public static PurchaseRequestItem Create(Guid company,Guid request,Guid variant,string uom,decimal qty)=>new(){Id=Guid.NewGuid(),CompanyId=company,PurchaseRequestId=request,ProductVariantId=variant,UomCode=InventoryText.Code(uom),RequestedQuantity=qty};}
public sealed class PurchaseOrder
{
 private PurchaseOrder(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid SupplierId{get;private set;}public Guid WarehouseId{get;private set;}public string PurchaseOrderNumber{get;private set;}="";public string CurrencyCode{get;private set;}="";public DateOnly? ExpectedDeliveryDate{get;private set;}public PurchaseOrderStatus Status{get;private set;}public string? ClosureReason{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static PurchaseOrder Create(Guid company,Guid supplier,Guid warehouse,string number,string currency,DateOnly?delivery,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,SupplierId=supplier,WarehouseId=warehouse,PurchaseOrderNumber=number,CurrencyCode=InventoryText.Code(currency),ExpectedDeliveryDate=delivery,Status=PurchaseOrderStatus.Draft,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1};public Result Submit(long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);if(Status!=PurchaseOrderStatus.Draft)return Result.Failure(InventoryErrors.InvalidTransition);Status=PurchaseOrderStatus.Submitted;UpdatedAtUtc=now;Version++;return Result.Success();}public void MarkReceipt(bool complete,DateTimeOffset now){Status=complete?PurchaseOrderStatus.Received:PurchaseOrderStatus.PartiallyReceived;UpdatedAtUtc=now;Version++;}public Result Close(bool cancel,string?reason,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(InventoryErrors.Concurrency);string? r=InventoryText.Text(reason,500);if(cancel&&r is null)return Result.Failure(InventoryErrors.ReasonRequired);if(cancel&&Status is PurchaseOrderStatus.Received or PurchaseOrderStatus.Closed||!cancel&&Status is not(PurchaseOrderStatus.Submitted or PurchaseOrderStatus.PartiallyReceived or PurchaseOrderStatus.Received))return Result.Failure(InventoryErrors.InvalidTransition);Status=cancel?PurchaseOrderStatus.Cancelled:PurchaseOrderStatus.Closed;ClosureReason=r;UpdatedAtUtc=now;Version++;return Result.Success();}
}
public sealed class PurchaseOrderItem{private PurchaseOrderItem(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid PurchaseOrderId{get;private set;}public Guid ProductVariantId{get;private set;}public string UomCode{get;private set;}="";public decimal OrderedQuantity{get;private set;}public decimal UnitPurchasePrice{get;private set;}public static PurchaseOrderItem Create(Guid company,Guid po,Guid variant,decimal qty,decimal price)=>Create(company,po,variant,"",qty,price);public static PurchaseOrderItem Create(Guid company,Guid po,Guid variant,string uom,decimal qty,decimal price)=>new(){Id=Guid.NewGuid(),CompanyId=company,PurchaseOrderId=po,ProductVariantId=variant,UomCode=InventoryText.Code(uom),OrderedQuantity=qty,UnitPurchasePrice=Money.Round(price)};}
public sealed class PurchaseReceipt{private PurchaseReceipt(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid PurchaseOrderId{get;private set;}public Guid PurchaseOrderItemId{get;private set;}public Guid StockTransactionId{get;private set;}public decimal Quantity{get;private set;}public string Reference{get;private set;}="";public Guid ReceivedByUserId{get;private set;}public DateTimeOffset ReceivedAtUtc{get;private set;}public static PurchaseReceipt Create(Guid company,Guid po,Guid item,Guid transaction,decimal qty,string reference,Guid actor,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,PurchaseOrderId=po,PurchaseOrderItemId=item,StockTransactionId=transaction,Quantity=qty,Reference=InventoryText.Code(reference),ReceivedByUserId=actor,ReceivedAtUtc=now};}
public sealed class PurchasingHistory{private PurchasingHistory(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public string EntityType{get;private set;}="";public Guid EntityId{get;private set;}public string EventType{get;private set;}="";public Guid ActorUserId{get;private set;}public DateTimeOffset OccurredAtUtc{get;private set;}public string? Summary{get;private set;}public static PurchasingHistory Create(Guid company,string entity,Guid id,string type,Guid actor,DateTimeOffset now,string?summary=null)=>new(){Id=Guid.NewGuid(),CompanyId=company,EntityType=entity,EntityId=id,EventType=type,ActorUserId=actor,OccurredAtUtc=now,Summary=InventoryText.Text(summary,500)};}
